/**
 * Reads demo data.
 */
declare abstract class DemoFacade {
    /**
     * Loads one demo by code.
     *
     * @param code Demo code
     * @param options Load options
     */
    abstract load(code: string, options?: {
        force?: boolean;
    }): void;
    abstract reset(): void;
}

interface DemoState {
    code?: string;
    separator: '}';
}

type DemoUnion = DemoState | null;

declare function overloaded(value: string): string;
declare function overloaded(value: number): number;

declare const demoTranslations: {
    en: Record<string, string>;
};

declare const es: Record<string, string>;

export { DemoFacade, demoTranslations, es as demoTranslationsEs };
export type { DemoState as PublicDemoState, DemoUnion };
